package jp.reader.manga;
import java.io.*;import java.util.*;
class Dav { static final class Item {String url,name;boolean dir;long createdAt; Item(String u,String n,boolean d){this(u,n,d,0);} Item(String u,String n,boolean d,long c){url=u;name=n;dir=d;createdAt=c;}} byte[] file;long transferred;int rangeCalls;Dav(byte[] x){file=x;}static class Range {byte[] data;long total;Range(byte[] b,long t){data=b;total=t;}} Range range(String u,long start,long end) throws Exception{rangeCalls++;int a=(int)(start<0?Math.max(0,file.length-end):start);int b=(int)(start<0?file.length-1:Math.min(file.length-1,end)); if(a<0||b<a)throw new IOException();byte[] x=Arrays.copyOfRange(file,a,b+1);transferred+=x.length;return new Range(x,file.length);} static byte[] read(InputStream in,int max)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[1024];int n;while((n=in.read(x))!=-1){if(b.size()+n>max)throw new IOException();b.write(x,0,n);}return b.toByteArray();} }
